import{_ as i,o as a,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS G/H (Day 1) - OSD review","description":"","frontmatter":{"title":"CDS G/H (Day 1) - OSD review","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-25T00:00:00.000Z","tags":["Ceph","OSD","RocksDB","Kinetic Drive","Storage Backend"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_OSD_review.md","filePath":"posts/2014/CDS_G_H_Day_1_-_OSD_review.md","lastUpdated":1780459816000}'),r={name:"posts/2014/CDS_G_H_Day_1_-_OSD_review.md"};function o(s,e,n,_,D,c){return a(),l("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要-ceph-osd-后端讨论" tabindex="-1">会议纪要：Ceph OSD 后端讨论 <a class="header-anchor" href="#会议纪要-ceph-osd-后端讨论" aria-label="Permalink to &quot;会议纪要：Ceph OSD 后端讨论&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次会议主要围绕Ceph的OSD（Object Storage Daemon）后端技术展开讨论。重点讨论了RocksDB和Kinetic Drive的相关工作进展，以及多个正在进行的项目和未来的发展方向。</p><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>OSD后端抽象</strong>：</p><ul><li>OSD内部有一个名为object store的抽象层，用于与本地存储（通常是文件系统和磁盘）进行交互。</li><li>目前主要使用的实现是file store，它将对象存储为文件。</li></ul></li><li><p><strong>新后端实现</strong>：</p><ul><li><strong>memstore</strong>：一个内存中的后端，主要用于基准测试和验证集群性能。</li><li><strong>key value store</strong>：一个新的后端实现，将所有数据存储在类似LevelDB的键值存储中，适用于特定的负载。</li><li><strong>RocksDB</strong>：一个即将加入的键值存储后端，特别优化用于SSD，预计将提供高性能。</li></ul></li><li><p><strong>Kinetic Drive</strong>：</p><ul><li>Kinetic Drive是一种具有以太网接口的硬盘，使用TCP协议进行通信，内部集成了键值数据库。</li><li>讨论了如何将Ceph的键值存储抽象与Kinetic API结合，以便利用这种新型硬盘。</li></ul></li><li><p><strong>性能优化</strong>：</p><ul><li>讨论了OSD消息调度的改进，以及如何通过优化减少CPU使用和锁竞争。</li><li>提到了RocksDB在并行压缩和读取方面的性能优势。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>确认了RocksDB后端的开发和测试进展，预计将很快合并到主分支。</li><li>对于Kinetic Drive的支持，虽然还有一些技术问题需要解决，但整体进展顺利。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续优化和测试RocksDB后端，确保其稳定性和性能。</li><li>解决Kinetic Drive集成中的技术问题，推动其向生产环境迈进。</li><li>探索其他键值存储后端的可能性，如nvm kv接口，以进一步扩展OSD的功能和性能。</li><li>讨论了如何更好地管理OSD进程的内存使用，特别是在资源受限的环境中。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h4><ul><li>讨论了如何更好地管理OSD进程的内存使用，特别是在资源受限的环境中。</li><li>提到了Ceph社区对不同版本LevelDB的测试和评估，以及对新存储技术的开放态度。</li></ul><p>本次会议为Ceph的OSD后端技术发展提供了清晰的路线图，并强调了社区合作和创新的重要性。</p>',12)])])}const p=i(r,[["render",o]]);export{d as __pageData,p as default};
